{
  "task_id": "reverse_hamming74_sec_decoder",
  "domain_id": "hardware_reverse_engineering",
  "title": "Recover a Hamming(7,4) single-error-correcting decoder",
  "description": "Reverse engineer a flattened, obfuscated gate-level netlist of a combinational Hamming(7,4) single-error-correcting decoder and re-implement it as clean, independently written RTL that is behaviorally identical to the reference for all 128 possible 7-bit codeword inputs.",
  "input_artifacts": [
    "inputs/flattened_netlist.v",
    "inputs/design_brief.md"
  ],
  "submission_artifacts": [
    "submission/recovered_rtl.v"
  ],
  "interface": {
    "module": "recovered_decoder",
    "ports": [
      { "name": "codeword", "direction": "input", "width": 7 },
      { "name": "data", "direction": "output", "width": 4 },
      { "name": "corrected_codeword", "direction": "output", "width": 7 },
      { "name": "error_detected", "direction": "output", "width": 1 }
    ],
    "style": "purely combinational, no clocks or internal state"
  },
  "evaluation": {
    "mode": "simulate",
    "toolchain": ["iverilog", "vvp", "yosys"],
    "test_vectors": "all 128 exhaustive values of codeword (7'b0000000 through 7'b1111111), each held for a #5 settling delay before sampling outputs",
    "metrics": [
      {
        "name": "word_recovery_rate",
        "description": "Fraction of the 128 exhaustive input codewords for which data[3:0] exactly matches the reference decoder output.",
        "direction": "maximize"
      },
      {
        "name": "structural_match_accuracy",
        "description": "Fraction of the 128 exhaustive input codewords for which corrected_codeword[6:0] and error_detected exactly match the reference decoder output, verifying correct syndrome computation and bit-flip correction.",
        "direction": "maximize"
      },
      {
        "name": "functional_equivalence",
        "description": "Boolean pass/fail: 1 if all three outputs (data, corrected_codeword, error_detected) match the reference for all 128 input codewords under iverilog/vvp simulation, else 0.",
        "direction": "maximize"
      }
    ]
  },
  "baselines": [
    "HAL benchmarks",
    "ISCAS'85",
    "ITC'99"
  ]
}

module flattened_netlist (
  input  [6:0] codeword,
  output [3:0] data,
  output [6:0] corrected_codeword,
  output       error_detected
);

  wire n1, n2, n3, n4, n5, n6, n7, n8, n9, n10, n11, n12;
  wire _T_1, _T_2, _T_3;
  wire [2:0] n_syn;
  wire [7:1] n_flip;

  // --- opaque XOR fan-in trees (syndrome computation) ---
  xor (n1, codeword[0], codeword[2]);
  xor (n2, codeword[4], codeword[6]);
  xor (_T_1, n1, n2);

  xor (n3, codeword[1], codeword[2]);
  xor (n4, codeword[5], codeword[6]);
  xor (_T_2, n3, n4);

  xor (n5, codeword[3], codeword[4]);
  xor (n6, codeword[5], codeword[6]);
  xor (_T_3, n5, n6);

  assign n_syn[0] = _T_1;
  assign n_syn[1] = _T_2;
  assign n_syn[2] = _T_3;

  assign error_detected = n_syn[0] | n_syn[1] | n_syn[2];

  // --- decode syndrome (1-indexed bit position) into one-hot flip mask ---
  assign n_flip[1] = (n_syn == 3'd1);
  assign n_flip[2] = (n_syn == 3'd2);
  assign n_flip[3] = (n_syn == 3'd3);
  assign n_flip[4] = (n_syn == 3'd4);
  assign n_flip[5] = (n_syn == 3'd5);
  assign n_flip[6] = (n_syn == 3'd6);
  assign n_flip[7] = (n_syn == 3'd7);

  // --- apply flip mask to obtain corrected codeword ---
  wire n7a, n8a, n9a, n10a, n11a, n12a, n13a;
  xor (n7a,  codeword[0], n_flip[1]);
  xor (n8a,  codeword[1], n_flip[2]);
  xor (n9a,  codeword[2], n_flip[3]);
  xor (n10a, codeword[3], n_flip[4]);
  xor (n11a, codeword[4], n_flip[5]);
  xor (n12a, codeword[5], n_flip[6]);
  xor (n13a, codeword[6], n_flip[7]);

  assign corrected_codeword[0] = n7a;
  assign corrected_codeword[1] = n8a;
  assign corrected_codeword[2] = n9a;
  assign corrected_codeword[3] = n10a;
  assign corrected_codeword[4] = n11a;
  assign corrected_codeword[5] = n12a;
  assign corrected_codeword[6] = n13a;

  // --- extract recovered data word from corrected codeword ---
  wire n14, n15, n16, n17;
  buf (n14, corrected_codeword[6]);
  buf (n15, corrected_codeword[5]);
  buf (n16, corrected_codeword[4]);
  buf (n17, corrected_codeword[2]);

  assign data[3] = n14;
  assign data[2] = n15;
  assign data[1] = n16;
  assign data[0] = n17;

endmodule

module recovered_decoder (
  input  [6:0] codeword,
  output [3:0] data,
  output [6:0] corrected_codeword,
  output       error_detected
);

  // PLACEHOLDER SUBMISSION -- replace with your recovered RTL.
  // This stub does no analysis at all: it simply passes the codeword
  // through unchanged and never reports or corrects an error. It is
  // expected to fail the behavioral comparison against the reference
  // decoder for the large majority of the 128 exhaustive test codewords.

  assign data               = 4'b0000;
  assign corrected_codeword = codeword;
  assign error_detected     = 1'b0;

endmodule
